 t('Institutions','<b>CCS → NCMC</b> (national crisis management; command, control, coordination; CBRN emergencies)','<b>NDMA</b> — policies, plans, guidelines; <b>chaired by PM</b>','<b>NEC</b> — assists NDMA (Home Secretary leads)','<b>NDRF</b> — assists states; <b>NIDM</b> — training, capacity building','<b>State:</b> SDMA → <b>DDMA</b> → local bodies',w=26),
